query FemaleNidoranType($where: pokemon_bool_exp!, $limit: Int!) {
  pokemon(where: $where, limit: $limit) {
    id
    name
    pokemontypes(limit: 3) {
      type { name }
    }
  }
}

query FemaleNidoranType($where: pokemon_bool_exp!, $limit: Int!, $typeLimit: Int!) {
  pokemon(where: $where, limit: $limit) {
    id
    name
    pokemontypes(limit: $typeLimit, order_by: {slot: asc}) {
      slot
      type {
        id
        name
      }
    }
  }
}

query GetMrMime($where: pokemon_bool_exp!, $statName: String!, $limit: Int!, $relationLimit: Int!) {
  pokemon(where: $where, limit: $limit) {
    id
    name
    pokemontypes(limit: $relationLimit, order_by: {slot: asc}) {
      slot
      type { name }
    }
    pokemonstats(limit: $relationLimit, where: {stat: {name: {_eq: $statName}}}) {
      base_stat
      stat { name }
    }
  }
}

